// Word flash: a black-and-white type spot cut on every hit of its track, timed frame by frame to a reference
// reel (positions, sizes, scales and entry moves measured off its frames). One word, or a two-word lockup, per cut;
// the background swaps black/white at every cut. The intro rises out of a blur, slides in from the left and pushes
// in; the run of words lands 1.2x large and settles, under film dust; the last word types on and blurs away.
//
// A component: the copy and the cuts are in script.ts, and tools/cuts.mjs makes cuts for another track. The audio
// (public/audio.m4a) is the reference's and is not committed.
//
// Render from the kinetograph-ui root:
//   node ../kinetograph/packages/cli/dist/cli.js strip templates/word-flash/index.tsx -n 24 -o templates/word-flash/out/strip.png
//   node ../kinetograph/packages/cli/dist/cli.js render templates/word-flash/index.tsx -o templates/word-flash/out/word-flash.mp4

import React from 'react';
import { Audio, Composition, interpolate, registerRoot, staticFile, useCurrentFrame } from 'remotion';
import { Ellipse, Layer, Rect, blur } from '@kinetographdev/core';
import { clamp } from './scenes/shared/kit/core/timing.js';
import { DARK, Dust, FPS, H, LIGHT, W, Word, ribbon, smear, directionalBlur, fit, grainBlur, ink } from './scenes/lib.js';
import { CUTS, END, SCRIPT } from './scenes/script.js';

/** a measured curve, one value a frame from the cut, held after its end */
const curve = (t: number, v: number[]) => interpolate(t, v.map((_, i) => i), v, clamp);

/** how a run word settles: scale against its resting size, frame by frame from the cut (measured) */
const SETTLE = [1.216, 1.134, 1.1, 1.08, 1.062, 1.046, 1.035, 1.024, 1.015, 1.008, 1.002, 0.998, 0.995, 0.993, 0.991];
/** the run's type size and baseline */
const RUN_W = { word: 'precision', width: 638 };
const RUN_BASELINE = 975;
/** run words whose ink centre sits off the middle in the reference */
const RUN_CX: Record<number, number> = { 0: 533, 1: 534, 2: 533, 3: 539 };

type ShotProps = { t: number; f: number; ink: string; bg: string };

// ---- intro ----

const [FIRST, SECOND, THIRD, FOURTH, FIFTH] = SCRIPT.intro;
const SMALL = { cx: 541.5, bottom: 916, width: 308 };
const BIG = { left: 151, bottom: 1136, width: 784 };
const SIDE = { left: 108, bottom: 814, width: 276 };
const SIDE_BIG = { left: 109, bottom: 1115, width: 849 };
const PUSH = { cx: 532, bottom: 1109, width: 693 };

/** the small word, rising out of a grainy vertical blur */
const Small: React.FC<{ color: string; t?: number }> = ({ color, t = 99 }) => {
  const sy = curve(t, [16, 8, 5, 3.5, 2.5, 2.2, 1.5, 1.2, 0.8, 0.5, 0]);
  return (
    <Layer effects={sy > 0.3 ? [grainBlur(sy * 0.5, sy * 1.6)] : []}>
      <Word text={FIRST} size={fit(FIRST, SMALL.width)} at={SMALL} color={color} />
    </Layer>
  );
};

const Intro: React.FC<ShotProps & { i: number }> = ({ i, t, ink }) => {
  if (i === 0) return <Small color={ink} t={t} />;
  if (i === 1) {
    const len = curve(t, [50, 6, 2, 0]);
    return (
      <>
        <Small color={ink} />
        <Layer effects={len > 0.5 ? [smear(len)] : []}>
          <Word text={SECOND} size={fit(SECOND, BIG.width)} at={BIG} color={ink} />
        </Layer>
      </>
    );
  }
  const side = <Word text={THIRD} size={fit(THIRD, SIDE.width)} at={SIDE} color={ink} />;
  if (i === 2) {
    const dx = curve(t, [-130, -83, -61, -46, -36, -27, -21, -16, -12, -9, -6, -4, -2, -1, -1, 0]);
    const v = Math.abs(curve(t + 1, [-130, -83, -61, -46, -36, -27, -21, -16, -12, -9, -6, -4, -2, -1, -1, 0]) - dx);
    return <Layer x={dx} effects={t < 6 ? [directionalBlur(Math.max(v, 14) * 0.35, 1, 0)] : []}>{side}</Layer>;
  }
  if (i === 3)
    return (
      <>
        {side}
        <Word text={FOURTH} size={fit(FOURTH, SIDE_BIG.width)} at={SIDE_BIG} color={ink} />
      </>
    );
  const s = curve(t, [0.871, 0.913, 0.943, 0.959, 0.971, 0.978, 0.984, 0.987, 0.991, 0.994, 0.995, 0.997, 0.998, 0.999, 1]);
  return <Word text={FIFTH} size={fit(FIFTH, PUSH.width)} at={PUSH} color={ink} scale={s} />;
};

// ---- the run ----

const runSize = () => fit(RUN_W.word, RUN_W.width);

/** The first run word bends in on a sine that flattens out over six frames, then settles a little. */
const Bent: React.FC<ShotProps> = ({ t, ink: color }) => {
  const text = SCRIPT.run[0];
  const amp = curve(t, [95, 55, 18, 7, 2, 0]);
  const thin = curve(t, [0.03, 0.12, 0.45, 0.8, 0.95, 1]);
  const s = curve(t, [1.051, 1.051, 1.051, 1.051, 1.051, 1.051, 1.04, 1.031, 1.022, 1.013, 1.009, 1.004, 1, 1]);
  const size = runSize();
  const k = ink(text);
  return (
    <Layer effects={thin < 0.995 ? [ribbon(amp, thin, RUN_CX[0] - ((k.r - k.l) * size) / 2, (k.r - k.l) * size, RUN_BASELINE - 0.25 * size)] : []}>
      <Word text={text} size={size} at={{ cx: RUN_CX[0], baseline: RUN_BASELINE }} color={color} scale={s} />
    </Layer>
  );
};

/** The second run word lands large like the rest, but its i comes in dotless and the dot drops onto it. */
const Dotted: React.FC<ShotProps> = ({ t, ink: color }) => {
  const text = SCRIPT.run[1];
  const size = runSize();
  const s = curve(t, [1.226, 1.144, 1.112, 1.089, 1.071, 1.055, 1.043, 1.033, 1.024, 1.016, 1.012, 1.008, 1.004, 1]);
  const at = { cx: RUN_CX[1], baseline: RUN_BASELINE };
  const i = Array.from(text).indexOf('i');
  if (i < 0) return <Word text={text} size={size} at={at} color={color} scale={s} />;
  const stem = ink('ı');
  const dot = ink('i');
  const d = (stem.r - stem.l) * size * 1.12;
  const drop = curve(t, [-999, -0.2, -0.09, 0]) * size;
  const k = ink(text);
  return (
    <Word
      text={text.replace('i', 'ı')}
      size={size}
      at={at}
      color={color}
      scale={s}
      extra={(pen) =>
        t >= 1 ? (
          <Ellipse
            x={pen.x + (k.pens[i] + (dot.l + dot.r) / 2) * size - d / 2}
            y={pen.y + dot.top * size + drop}
            width={d}
            height={d}
            fill={color}
          />
        ) : null
      }
    />
  );
};

const Settle: React.FC<ShotProps & { n: number }> = ({ n, t, ink: color }) => (
  <Word text={SCRIPT.run[n]} size={runSize()} at={{ cx: RUN_CX[n] ?? 540, baseline: RUN_BASELINE }} color={color} scale={curve(t, SETTLE)} />
);

// ---- the outro ----

const FINAL = SCRIPT.outro[SCRIPT.outro.length - 1];
const OUT = { width: 491, baseline: 971 };
/** how far each typed stage settles, by stage from the first (measured: the first shrinks most, the last not at all) */
const STAGE_SETTLE = [
  [1.145, 1.076, 1.055, 1.034, 1.028, 1.014, 1],
  [1.042, 1.037, 1.028, 1.022, 1.017, 1.014, 1.008, 1.003, 1],
  [1.015, 1.015, 1.01, 1.01, 1.005, 1.005, 1.002, 1],
];

const Typed: React.FC<ShotProps & { n: number; hold?: boolean }> = ({ n, t, ink: color, hold }) => {
  const text = SCRIPT.outro[n];
  const settle = STAGE_SETTLE[n];
  const s = settle ? curve(t, settle) : 1;
  const out = hold && t >= CUTS[CUTS.length - 1] - CUTS[CUTS.length - 2] - 1;
  return (
    <Layer effects={out ? [blur(3.5)] : []}>
      <Word text={text} size={fit(FINAL, OUT.width)} at={{ cx: 540.5, baseline: OUT.baseline }} color={color} scale={out ? 0.985 : s} />
    </Layer>
  );
};

// ---- the spot ----

const INTRO = SCRIPT.intro.length;
const RUN = SCRIPT.run.length;
const OUTRO = SCRIPT.outro.length;

export const WordFlash: React.FC = () => {
  const f = useCurrentFrame();
  let i = CUTS.length - 1;
  while (i > 0 && CUTS[i] > f) i--;
  const t = f - CUTS[i];
  // black and white swap every cut through the hold; the blank after it keeps the hold's
  const swaps = Math.min(i, INTRO + RUN + OUTRO);
  const light = swaps % 2 === 0;
  const p: ShotProps = { t, f, ink: light ? DARK : LIGHT, bg: light ? LIGHT : DARK };
  const run = i - INTRO;
  const out = i - INTRO - RUN;
  const dusty = run >= 2 && run < RUN;
  return (
    <Layer>
      <Rect width={W} height={H} fill={p.bg} />
      {i < INTRO ? <Intro {...p} i={i} /> : null}
      {run === 0 ? <Bent {...p} /> : null}
      {run === 1 ? <Dotted {...p} /> : null}
      {run >= 2 && run < RUN ? <Settle {...p} n={run} /> : null}
      {out >= 0 && out < OUTRO ? <Typed {...p} n={out} /> : null}
      {out === OUTRO ? <Typed {...p} n={OUTRO - 1} hold /> : null}
      {dusty ? <Dust f={f} color={light ? '#2a2a2a' : '#e8e8e8'} /> : null}
      <Audio src={staticFile('audio.m4a')} />
    </Layer>
  );
};

registerRoot(() => <Composition id="WordFlash" component={WordFlash} durationInFrames={END} fps={FPS} width={W} height={H} />);

// What every shot shares: the canvas, the two colours, the type (Figtree Bold set tight, standing in for the
// reference's Proxima-style sans), ink measurement so a word can be placed and scaled by its ink box the way an
// After Effects text layer with its anchor at the content's centre is, and the three entry shaders.

import React from 'react';
import { random } from 'remotion';
import { Canvas, Layer, Text, shader } from '@kinetographdev/core';
import { makeGoogleFont } from '@kinetographdev/core/google-fonts';

export const W = 1080;
export const H = 1920;
export const FPS = 30;

export const LIGHT = '#f7f7f7';
export const DARK = '#050505';

export const FONT = makeGoogleFont('Figtree').loadFont('normal', { weights: ['700'] }).fontFamily;
export const WEIGHT = 700;
/** tracking, em */
export const TRACK = -0.06;
/** the baseline below a Text's y, em (Figtree, default line height) */
const BASE = 0.955;

// ---- ink ----

export interface Ink {
  /** ink edges, em, from the pen at the start of the baseline; top and bottom are y down */
  l: number;
  r: number;
  top: number;
  bottom: number;
  /** each character's pen position, em, tracking included */
  pens: number[];
}

type Surface = { getContext(type: '2d', options?: unknown): any };
let surface: Surface | null = null;
const inks = new Map<string, Ink>();
const G = 200; // px per em when measuring

/** The word's ink box, drawn once on an OffscreenCanvas with the same tracking Text gets and read back. */
export function ink(text: string): Ink {
  const hit = inks.get(text);
  if (hit) return hit;
  const Offscreen = (globalThis as { OffscreenCanvas?: new (w: number, h: number) => Surface }).OffscreenCanvas;
  if (!Offscreen) throw new Error('word-flash measures type with OffscreenCanvas: render it with Kinetograph');
  const [cw, ch] = [G * Math.max(4, text.length + 2), G * 2];
  surface ??= new Offscreen(G * 16, ch);
  const ctx = surface.getContext('2d', { willReadFrequently: true });
  ctx.clearRect(0, 0, G * 16, ch);
  ctx.font = `${WEIGHT} ${G}px ${FONT}`;
  ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#fff';
  const [ox, base] = [G / 2, G * 1.3];
  const chars = Array.from(text);
  const pens = chars.map((_, k) => ctx.measureText(chars.slice(0, k).join('')).width + k * TRACK * G);
  chars.forEach((c, k) => ctx.fillText(c, ox + pens[k], base));
  const px: Uint8ClampedArray = ctx.getImageData(0, 0, cw, ch).data;
  let [l, r, t, b] = [cw, -1, ch, -1];
  for (let y = 0; y < ch; y++)
    for (let x = 0; x < cw; x++)
      if (px[(y * cw + x) * 4 + 3] > 100) {
        if (x < l) l = x;
        if (x > r) r = x;
        if (y < t) t = y;
        if (y > b) b = y;
      }
  const out: Ink = { l: (l - ox) / G, r: (r + 1 - ox) / G, top: (t - base) / G, bottom: (b + 1 - base) / G, pens: pens.map((p) => p / G) };
  inks.set(text, out);
  return out;
}

/** The size at which the word's ink is w pixels wide. */
export const fit = (text: string, w: number) => {
  const k = ink(text);
  return w / (k.r - k.l);
};

// ---- a word ----

export interface Place {
  /** ink centre x, or ink left / right edge */
  cx?: number;
  left?: number;
  right?: number;
  /** baseline y, or the ink's bottom edge */
  baseline?: number;
  bottom?: number;
}

/** A word placed by its ink and scaled about its ink centre. `chars` styles go to the Text as they are. */
export const Word: React.FC<{
  text: string;
  size: number;
  at: Place;
  color: string;
  scale?: number;
  dx?: number;
  dy?: number;
  chars?: (c: string, k: number) => Record<string, number | string> | null;
  /** more to draw in the word's frame, given where its pen starts on the baseline */
  extra?: (pen: { x: number; y: number }) => React.ReactNode;
}> = ({ text, size, at, color, scale = 1, dx = 0, dy = 0, chars, extra }) => {
  const k = ink(text);
  const w = (k.r - k.l) * size;
  const left = at.left ?? (at.right !== undefined ? at.right - w : (at.cx ?? W / 2) - w / 2);
  const baseline = at.baseline ?? (at.bottom ?? H / 2) - k.bottom * size;
  const pen = left - k.l * size;
  const px = left + w / 2;
  const py = baseline + ((k.top + k.bottom) / 2) * size;
  return (
    <Layer x={px + dx} y={py + dy} scale={scale}>
      <Text
        font={FONT}
        weight={WEIGHT}
        size={size}
        color={color}
        x={pen - px}
        y={baseline - BASE * size - py}
        chars={Array.from(text).map((c, i) => ({ x: i * TRACK * size, ...(chars?.(c, i) ?? {}) }))}
      >
        {text}
      </Text>
      {extra?.({ x: pen - px, y: baseline - py })}
    </Layer>
  );
};

// ---- shaders ----

/** A Gaussian blur along one direction (dx, dy), sigma in pixels. */
export const directionalBlur = (sigma: number, dx = 0, dy = 1) =>
  shader({
    code: `fn effect(px: vec2<f32>) -> vec4<f32> {
  let s = max(u.sigma, 0.001);
  var acc = vec4<f32>(0.0);
  var sum = 0.0;
  for (var i = -16; i <= 16; i++) {
    let t = f32(i) / 16.0 * 2.6 * s;
    let w = exp(-0.5 * (t / s) * (t / s));
    acc += layer(px + vec2<f32>(u.dx, u.dy) * t) * w;
    sum += w;
  }
  return acc / sum;
}`,
    uniforms: { sigma, dx, dy },
    padding: Math.ceil(sigma * 3),
  });

/** A grainy blur: every pixel reads a few points scattered round it, so edges dissolve into specks. */
export const grainBlur = (sx: number, sy: number) =>
  shader({
    code: `fn hash2(p: vec2<f32>) -> f32 { return fract(sin(dot(p, vec2<f32>(12.9898, 78.233))) * 43758.5453); }
fn effect(px: vec2<f32>) -> vec4<f32> {
  var acc = vec4<f32>(0.0);
  for (var i = 0; i < 3; i++) {
    let o = f32(i) * 7.31 + globals.frame * 1.7;
    let r = vec2<f32>(hash2(px + o) - 0.5, hash2(px * 1.37 + o + 3.1) - 0.5);
    acc += layer(px + r * 2.0 * vec2<f32>(u.sx, u.sy));
  }
  return acc / 3.0;
}`,
    uniforms: { sx, sy },
    padding: Math.ceil(Math.max(sx, sy)),
  });

/** A tapered wave across a word from x0, w wide, about the line y = cy: its left end squashed to a thin line
 *  (`thin` of its height) and widening to full height on the right, the whole lifted along an arc of `amp` pixels
 *  that dips on the left and peaks two thirds along. Both go to nothing as thin goes to 1 and amp to 0. */
export const ribbon = (amp: number, thin: number, x0: number, w: number, cy: number) =>
  shader({
    code: `fn effect(px: vec2<f32>) -> vec4<f32> {
  let x = (px.x - u.x0) / u.w;
  let sy = mix(u.thin, 1.0, smoothstep(-0.1, 1.0, x));
  let off = -u.amp * sin((x - 0.3) * 3.1415927 * 1.25);
  return layer(vec2<f32>(px.x, u.cy + (px.y - u.cy - off) / sy));
}`,
    uniforms: { amp, thin, x0, w, cy },
    padding: Math.ceil(Math.abs(amp) * 1.5),
  });

/** A one-sided smear: every pixel also reads up to len pixels back along (dx, dy), under the layer itself, so a
 *  word that has just moved that way stays sharp and trails behind it. */
export const smear = (len: number, dx = 0, dy = -1) =>
  shader({
    code: `fn effect(px: vec2<f32>) -> vec4<f32> {
  var acc = vec4<f32>(0.0);
  for (var i = 0; i < 24; i++) {
    acc += layer(px + vec2<f32>(u.dx, u.dy) * u.len * f32(i) / 23.0) * (1.0 - f32(i) / 24.0);
  }
  let own = layer(px);
  return own + (1.0 - own.a) * acc / 12.5;
}`,
    uniforms: { len, dx, dy },
    padding: Math.ceil(len),
  });

// ---- dust ----

/** Film dust: specks scattered fresh every frame, light on dark and dark on light. */
export const Dust: React.FC<{ f: number; color: string; count?: number }> = ({ f, color, count = 110 }) => (
  <Canvas
    width={W}
    height={H}
    draw={(ctx: any) => {
      ctx.fillStyle = color;
      for (let i = 0; i < count; i++) {
        const r = (k: string) => random(`dust-${f}-${i}-${k}`);
        const s = 0.6 + 1.8 * r('s') ** 4;
        ctx.globalAlpha = 0.35 + 0.65 * r('a');
        ctx.beginPath();
        ctx.ellipse(r('x') * W, r('y') * H, s, s * (0.7 + 0.6 * r('e')), r('t') * 3.14, 0, Math.PI * 2);
        ctx.fill();
      }
    }}
  />
);

// The component's copy and its cuts. Change the words here; get cuts for another track with
// `node templates/word-flash/tools/cuts.mjs <audio>` (prints a CUTS line to paste in).
//
// One cut per shot, in order: the five intro shots (a small word, the small word over a big one, a third word
// sliding in, that word over a fourth, a fifth big alone), one shot per `run` word, one per `outro` stage, a hold on
// the last stage, and a blank. The background swaps black/white at every cut up to the hold.

export const SCRIPT = {
  intro: ['we', 'don’t', 'just', 'edit', 'we'] as const,
  run: ['create', 'motion', 'art', 'impact', 'visuals', 'energy', 'precision', 'rhythm', 'vibes', 'graphics', 'transitions', 'ideas', 'feelings'],
  /** the last word typed on in stages */
  outro: ['re', 'repe.', 'repea', 'repeat.'],
};

/** the frame each shot starts: the reference's cuts, one on every hit of its audio */
export const CUTS = [0, 22, 42, 60, 76, 91, 105, 119, 131, 142, 155, 166, 177, 187, 197, 207, 216, 225, 234, 241, 250, 258, 267, 276];
export const END = 282;

// Frame-based timing: eases, keyframes, ramps, and two smooth curves for camera paths measured key by key.

import { Easing, interpolate } from 'remotion';

export const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
export const ease = Easing.bezier(0.45, 0, 0.15, 1);
export const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
export const easeIn = Easing.bezier(0.7, 0, 0.84, 0);

/** interpolate over keyframes [[frame, value], ...] with one easing for every segment */
export function keys(f: number, k: [number, number][], easing: (t: number) => number = ease): number {
  if (f <= k[0][0]) return k[0][1];
  for (let i = 1; i < k.length; i++) {
    if (f <= k[i][0]) {
      const [a, va] = k[i - 1];
      const [b, vb] = k[i];
      return va + (vb - va) * easing((f - a) / (b - a));
    }
  }
  return k[k.length - 1][1];
}

/** from at frame a to to at frame b, held outside */
export const ramp = (f: number, a: number, b: number, from: number, to: number, easing = ease) =>
  interpolate(f, [a, b], [from, to], { ...clamp, easing });

/** A smooth curve through [frame, value] keys (cubic Hermite, finite-difference slopes, flat at the ends and where
 *  the direction turns), so a camera measured key by key moves without stopping at every key. */
export function spline(f: number, k: [number, number][]): number {
  if (f <= k[0][0]) return k[0][1];
  const n = k.length - 1;
  if (f >= k[n][0]) return k[n][1];
  const slope = (i: number) => {
    if (i === 0 || i === n) return 0;
    const a = (k[i][1] - k[i - 1][1]) / (k[i][0] - k[i - 1][0]);
    const b = (k[i + 1][1] - k[i][1]) / (k[i + 1][0] - k[i][0]);
    return a * b <= 0 ? 0 : (k[i + 1][1] - k[i - 1][1]) / (k[i + 1][0] - k[i - 1][0]);
  };
  let i = 0;
  while (f > k[i + 1][0]) i++;
  const [t0, v0] = k[i];
  const [t1, v1] = k[i + 1];
  const h = t1 - t0;
  const t = (f - t0) / h;
  const t2 = t * t;
  const t3 = t2 * t;
  return (2 * t3 - 3 * t2 + 1) * v0 + (t3 - 2 * t2 + t) * h * slope(i) + (-2 * t3 + 3 * t2) * v1 + (t3 - t2) * h * slope(i + 1);
}

/** Monotone cubic through keys [[frame, value], ...]: a camera that glides through its marks without stopping or
 *  overshooting them. */
export function glide(f: number, k: [number, number][]): number {
  const n = k.length;
  if (f <= k[0][0]) return k[0][1];
  if (f >= k[n - 1][0]) return k[n - 1][1];
  const d = k.map((_, i) => {
    if (i === 0 || i === n - 1) return 0;
    const s0 = (k[i][1] - k[i - 1][1]) / (k[i][0] - k[i - 1][0]);
    const s1 = (k[i + 1][1] - k[i][1]) / (k[i + 1][0] - k[i][0]);
    return s0 * s1 <= 0 ? 0 : (2 * s0 * s1) / (s0 + s1);
  });
  let i = 1;
  while (f > k[i][0]) i++;
  const [x0, y0] = k[i - 1];
  const [x1, y1] = k[i];
  const hh = x1 - x0;
  const t = (f - x0) / hh;
  const t2 = t * t;
  const t3 = t2 * t;
  return (
    (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * hh * d[i - 1] + (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * hh * d[i]
  );
}
